import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, Vector3 } = ctx.THREE;

  const group = new Group();
  group.name = 'hub-collection-card-3-label';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const accentColor = new Color(colors.accent);
  const inkColor = new Color(colors.ink);
  const paperColor = new Color(colors.paper);
  const surfaceColor = new Color(colors.surface);

  // --- Backdrop gradient plane (engineered gradient surface) ---
  const backdropMat = new MeshBasicNodeMaterial();
  const vUv = uv();
  const gradient = mix(vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b), vec3(inkColor.r, inkColor.g, inkColor.b), smoothstep(0.0, 1.0, vUv.y));
  const grainMod = smoothstep(0.0, 1.0, vUv.x).mul(0.04);
  backdropMat.colorNode = gradient.add(vec3(grainMod, grainMod, grainMod));
  backdropMat.transparent = true;
  backdropMat.opacity = 0.92;

  const backdropGeo = new PlaneGeometry(1.6, 0.5);
  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.z = -0.02;
  group.add(backdropMesh);

  // --- Image plane (feature card texture as accent strip) ---
  const cardMat = new MeshBasicNodeMaterial();
  cardMat.transparent = true;
  cardMat.opacity = 0.85;

  let cardMesh = null;
  if (config.imageUrl) {
    const cardGeo = new PlaneGeometry(0.18, 0.42);
    cardMesh = new Mesh(cardGeo, cardMat);
    cardMesh.position.x = -0.62;
    cardMesh.position.z = 0.01;
    group.add(cardMesh);

    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      cardMat.map = tex;
      cardMat.colorNode = undefined;
      cardMat.needsUpdate = true;
    });
  }

  // --- Accent divider line ---
  const accentMat = new MeshBasicNodeMaterial();
  accentMat.colorNode = vec3(accentColor.r, accentColor.g, accentColor.b);
  accentMat.transparent = true;
  accentMat.opacity = 0.9;
  const accentGeo = new PlaneGeometry(0.04, 0.42);
  const accentLine = new Mesh(accentGeo, accentMat);
  accentLine.position.x = -0.48;
  accentLine.position.z = 0.02;
  group.add(accentLine);

  // --- Text content ---
  const textObjects = [];
  for (const item of items) {
    const fontSize = item.typography?.fontSize ?? (item.role === 'headline' ? 39 : 13);
    const align = 'left';
    const textObj = ctx.fontAtlas.createText(String(item.text), {
      fontSize,
      color: colors.paper,
      align,
      letterSpacingPx: 0.5,
    });
    if (textObj) {
      textObj.position.set(-0.36, -0.08, 0.03);
      group.add(textObj);
      textObjects.push(textObj);
    }
  }

  // --- Subtle entrance motion (weighted-settle inspired) ---
  const tl = gsap.timeline();
  group.scale.set(0.92, 0.92, 1);
  group.userData.__targetScale = 1;
  tl.to(group.scale, {
    x: 1.04,
    y: 1.04,
    duration: 0.55,
    ease: 'power3.out',
  });
  tl.to(group.scale, {
    x: 1.0,
    y: 1.0,
    duration: 0.4,
    ease: 'power4.out',
  });

  // --- Cleanup ---
  group.userData.cleanup = () => {
    tl.kill();
    backdropGeo.dispose();
    backdropMat.dispose();
    if (cardMesh) {
      cardMesh.geometry.dispose();
      cardMat.dispose();
      if (cardMat.map) cardMat.map.dispose();
    }
    accentGeo.dispose();
    accentMat.dispose();
    textObjects.forEach((t) => {
      if (t.geometry) t.geometry.dispose();
      if (t.material) {
        if (Array.isArray(t.material)) t.material.forEach((m) => m.dispose());
        else t.material.dispose();
      }
    });
  };

  group.userData.handlers = {};

  return group;
}
